clc;
clear all;
close all;
 t=-5:0.01:5;   % time range
 x_t= rectpuls(t,2);  % rectangle pulse ka width

 figure(); %[output:39793993]
 subplot(2,1,1); %[output:39793993]
 plot(t,x_t); %[output:39793993]

 w=-pi:0.01:pi;
 x_k=zeros(size(w));

 for k= 1:length(w)     % perform fourier transform
     x_k(k)= trapz(t,x_t.*exp((-1)*2*pi*w(k)*t));
 end
magnitude_x_k = abs(x_k);
phase_x_k = angle(x_k);

subplot(3,1,2); %[output:64d86e81]
plot(k,magnitude_x_k,'LineWidth',1.5); %[output:64d86e81]
xlabel('frequency (hz)'); %[output:64d86e81]
ylabel('|x(k)|'); %[output:64d86e81]
title('magnitude spectrum of x(k)'); %[output:64d86e81]
grid on; %[output:64d86e81]

subplot(3,1,3); %[output:64d86e81]
plot(w,magnitude_x_k,'LineWidth',1.5); %[output:64d86e81]
xlabel('frequency (hz)'); %[output:64d86e81]
ylabel('phase (radian)'); %[output:64d86e81]
title('phase spectrum of x(k)'); %[output:64d86e81]
grid on; %[output:64d86e81]





